import{_ as t,o,c as r,l as s,t as a,N as i}from"./chunks/framework.Bbd9fWQx.js";const k=JSON.parse('{"title":"git-gc | x-cmd man (git man1) | Cleanup unnecessary files and optimize the local repository","titleTemplate":false,"description":"x-cmd man (git man1 Manual Page) | git-gc - Cleanup unnecessary files and optimize the local repository","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"git-gc | x-cmd man (git man1) | Cleanup unnecessary files and optimize the local repository"}],["meta",{"name":"og:description","content":"x-cmd man (git man1 Manual Page) | git-gc - Cleanup unnecessary files and optimize the local repository"}]]},"headers":[],"params":{"isMan":true,"man":"git-gc","category":"git man1","desc":"Cleanup unnecessary files and optimize the local repository"},"relativePath":"git/man1/git-gc.md","filePath":"git/man1/git-gc.md"}'),n={name:"git/man1/git-gc.md"},g={class:"visually-hidden"},l=i('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>git-gc - Cleanup unnecessary files and optimize the local repository</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gc</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--aggressive] [--auto] [--quiet] [--prune</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">date</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> --no-prune] [--force] [--keep-largest-pack]</span></span></code></pre></div><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>Runs a number of housekeeping tasks within the current repository, such as compressing file revisions (to reduce disk space and increase performance), removing unreachable objects which may have been created from prior invocations of <em>git add</em>, packing refs, pruning reflog, rerere metadata or stale working trees. May also update ancillary indexes such as the commit-graph.</p><p>When common porcelain operations that create objects are run, they will check whether the repository has grown substantially since the last maintenance, and if so run <strong>git gc</strong> automatically. See <strong>gc.auto</strong> below for how to disable this behavior.</p><p>Running <strong>git gc</strong> manually should only be needed when adding objects to a repository without regularly running such porcelain commands, to do a one-off repository optimization, or e.g. to clean up a suboptimal mass-import. See the &quot;PACKFILE OPTIMIZATION&quot; section in <strong>git-fast-import</strong>(1) for more details on the import case.</p><h2 id="options" tabindex="-1">OPTIONS <a class="header-anchor" href="#options" aria-label="Permalink to &quot;OPTIONS&quot;">​</a></h2><p>--aggressive</p><blockquote><p>Usually <em>git gc</em> runs very quickly while providing good disk space utilization and performance. This option will cause <em>git gc</em> to more aggressively optimize the repository at the expense of taking much more time. The effects of this optimization are mostly persistent. See the &quot;AGGRESSIVE&quot; section below for details.</p></blockquote><p>--auto</p><blockquote><p>With this option, <em>git gc</em> checks whether any housekeeping is required; if not, it exits without performing any work.</p><p>See the <strong>gc.auto</strong> option in the &quot;CONFIGURATION&quot; section below for how this heuristic works.</p><p>Once housekeeping is triggered by exceeding the limits of configuration options such as <strong>gc.auto</strong> and <strong>gc.autoPackLimit</strong>, all other housekeeping tasks (e.g. rerere, working trees, reflog...) will be performed as well.</p></blockquote><p>--cruft</p><blockquote><p>When expiring unreachable objects, pack them separately into a cruft pack instead of storing them as loose objects.</p></blockquote><p>--prune=&lt;date&gt;</p><blockquote><p>Prune loose objects older than date (default is 2 weeks ago, overridable by the config variable <strong>gc.pruneExpire</strong>). --prune=now prunes loose objects regardless of their age and increases the risk of corruption if another process is writing to the repository concurrently; see &quot;NOTES&quot; below. --prune is on by default.</p></blockquote><p>--no-prune</p><blockquote><p>Do not prune any loose objects.</p></blockquote><p>--quiet</p><blockquote><p>Suppress all progress reports.</p></blockquote><p>--force</p><blockquote><p>Force <strong>git gc</strong> to run even if there may be another <strong>git gc</strong> instance running on this repository.</p></blockquote><p>--keep-largest-pack</p><blockquote><p>All packs except the largest pack and those marked with a <strong>.keep</strong> files are consolidated into a single pack. When this option is used, <strong>gc.bigPackThreshold</strong> is ignored.</p></blockquote><h2 id="aggressive" tabindex="-1">AGGRESSIVE <a class="header-anchor" href="#aggressive" aria-label="Permalink to &quot;AGGRESSIVE&quot;">​</a></h2><p>When the <strong>--aggressive</strong> option is supplied, <strong>git-repack</strong>(1) will be invoked with the <strong>-f</strong> flag, which in turn will pass <strong>--no-reuse-delta</strong> to <strong>git-pack-objects</strong>(1). This will throw away any existing deltas and re-compute them, at the expense of spending much more time on the repacking.</p><p>The effects of this are mostly persistent, e.g. when packs and loose objects are coalesced into one another pack the existing deltas in that pack might get re-used, but there are also various cases where we might pick a sub-optimal delta from a newer pack instead.</p><p>Furthermore, supplying <strong>--aggressive</strong> will tweak the <strong>--depth</strong> and <strong>--window</strong> options passed to <strong>git-repack</strong>(1). See the <strong>gc.aggressiveDepth</strong> and <strong>gc.aggressiveWindow</strong> settings below. By using a larger window size we&#39;re more likely to find more optimal deltas.</p><p>It&#39;s probably not worth it to use this option on a given repository without running tailored performance benchmarks on it. It takes a lot more time, and the resulting space/delta optimization may or may not be worth it. Not using this at all is the right trade-off for most users and their repositories.</p><h2 id="configuration" tabindex="-1">CONFIGURATION <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;CONFIGURATION&quot;">​</a></h2><p>Everything below this line in this section is selectively included from the <strong>git-config</strong>(1) documentation. The content is the same as what&#39;s found there:</p><p>gc.aggressiveDepth</p><blockquote><p>The depth parameter used in the delta compression algorithm used by <em>git gc --aggressive</em>. This defaults to 50, which is the default for the <strong>--depth</strong> option when <strong>--aggressive</strong> isn&#39;t in use.</p><p>See the documentation for the <strong>--depth</strong> option in <strong>git-repack</strong>(1) for more details.</p></blockquote><p>gc.aggressiveWindow</p><blockquote><p>The window size parameter used in the delta compression algorithm used by <em>git gc --aggressive</em>. This defaults to 250, which is a much more aggressive window size than the default <strong>--window</strong> of 10.</p><p>See the documentation for the <strong>--window</strong> option in <strong>git-repack</strong>(1) for more details.</p></blockquote><p>gc.auto</p><blockquote><p>When there are approximately more than this many loose objects in the repository, <strong>git gc --auto</strong> will pack them. Some Porcelain commands use this command to perform a light-weight garbage collection from time to time. The default value is 6700.</p><p>Setting this to 0 disables not only automatic packing based on the number of loose objects, but any other heuristic <strong>git gc --auto</strong> will otherwise use to determine if there&#39;s work to do, such as <strong>gc.autoPackLimit</strong>.</p></blockquote><p>gc.autoPackLimit</p><blockquote><p>When there are more than this many packs that are not marked with <strong>*.keep</strong> file in the repository, <strong>git gc --auto</strong> consolidates them into one larger pack. The default value is 50. Setting this to 0 disables it. Setting <strong>gc.auto</strong> to 0 will also disable this.</p><p>See the <strong>gc.bigPackThreshold</strong> configuration variable below. When in use, it&#39;ll affect how the auto pack limit works.</p></blockquote><p>gc.autoDetach</p><blockquote><p>Make <strong>git gc --auto</strong> return immediately and run in background if the system supports it. Default is true.</p></blockquote><p>gc.bigPackThreshold</p><blockquote><p>If non-zero, all packs larger than this limit are kept when <strong>git gc</strong> is run. This is very similar to <strong>--keep-largest-pack</strong> except that all packs that meet the threshold are kept, not just the largest pack. Defaults to zero. Common unit suffixes of <em>k</em>, <em>m</em>, or <em>g</em> are supported.</p><p>Note that if the number of kept packs is more than gc.autoPackLimit, this configuration variable is ignored, all packs except the base pack will be repacked. After this the number of packs should go below gc.autoPackLimit and gc.bigPackThreshold should be respected again.</p><p>If the amount of memory estimated for <strong>git repack</strong> to run smoothly is not available and <strong>gc.bigPackThreshold</strong> is not set, the largest pack will also be excluded (this is the equivalent of running <strong>git gc</strong> with <strong>--keep-largest-pack</strong>).</p></blockquote><p>gc.writeCommitGraph</p><blockquote><p>If true, then gc will rewrite the commit-graph file when <strong>git-gc</strong>(1) is run. When using <strong>git gc --auto</strong> the commit-graph will be updated if housekeeping is required. Default is true. See <strong>git-commit-graph</strong>(1) for details.</p></blockquote><p>gc.logExpiry</p><blockquote><p>If the file gc.log exists, then <strong>git gc --auto</strong> will print its content and exit with status zero instead of running unless that file is more than <em>gc.logExpiry</em> old. Default is &quot;1.day&quot;. See <strong>gc.pruneExpire</strong> for more ways to specify its value.</p></blockquote><p>gc.packRefs</p><blockquote><p>Running <strong>git pack-refs</strong> in a repository renders it unclonable by Git versions prior to 1.5.1.2 over dumb transports such as HTTP. This variable determines whether <em>git gc</em> runs <strong>git pack-refs</strong>. This can be set to <strong>notbare</strong> to enable it within all non-bare repos or it can be set to a boolean value. The default is <strong>true</strong>.</p></blockquote><p>gc.cruftPacks</p><blockquote><p>Store unreachable objects in a cruft pack (see <strong>git-repack</strong>(1)) instead of as loose objects. The default is <strong>false</strong>.</p></blockquote><p>gc.pruneExpire</p><blockquote><p>When <em>git gc</em> is run, it will call <em>prune --expire 2.weeks.ago</em> (and <em>repack --cruft --cruft-expiration 2.weeks.ago</em> if using cruft packs via <strong>gc.cruftPacks</strong> or <strong>--cruft</strong>). Override the grace period with this config variable. The value &quot;now&quot; may be used to disable this grace period and always prune unreachable objects immediately, or &quot;never&quot; may be used to suppress pruning. This feature helps prevent corruption when <em>git gc</em> runs concurrently with another process writing to the repository; see the &quot;NOTES&quot; section of <strong>git-gc</strong>(1).</p></blockquote><p>gc.worktreePruneExpire</p><blockquote><p>When <em>git gc</em> is run, it calls <em>git worktree prune --expire 3.months.ago</em>. This config variable can be used to set a different grace period. The value &quot;now&quot; may be used to disable the grace period and prune <strong>$GIT_DIR/worktrees</strong> immediately, or &quot;never&quot; may be used to suppress pruning.</p></blockquote><p>gc.reflogExpire, gc.&lt;pattern&gt;.reflogExpire</p><blockquote><p><em>git reflog expire</em> removes reflog entries older than this time; defaults to 90 days. The value &quot;now&quot; expires all entries immediately, and &quot;never&quot; suppresses expiration altogether. With &quot;&lt;pattern&gt;&quot; (e.g. &quot;refs/stash&quot;) in the middle the setting applies only to the refs that match the &lt;pattern&gt;.</p></blockquote><p>gc.reflogExpireUnreachable, gc.&lt;pattern&gt;.reflogExpireUnreachable</p><blockquote><p><em>git reflog expire</em> removes reflog entries older than this time and are not reachable from the current tip; defaults to 30 days. The value &quot;now&quot; expires all entries immediately, and &quot;never&quot; suppresses expiration altogether. With &quot;&lt;pattern&gt;&quot; (e.g. &quot;refs/stash&quot;) in the middle, the setting applies only to the refs that match the &lt;pattern&gt;.</p><p>These types of entries are generally created as a result of using <strong>git commit --amend</strong> or <strong>git rebase</strong> and are the commits prior to the amend or rebase occurring. Since these changes are not part of the current project most users will want to expire them sooner, which is why the default is more aggressive than <strong>gc.reflogExpire</strong>.</p></blockquote><p>gc.rerereResolved</p><blockquote><p>Records of conflicted merge you resolved earlier are kept for this many days when <em>git rerere gc</em> is run. You can also use more human-readable &quot;1.month.ago&quot;, etc. The default is 60 days. See <strong>git-rerere</strong>(1).</p></blockquote><p>gc.rerereUnresolved</p><blockquote><p>Records of conflicted merge you have not resolved are kept for this many days when <em>git rerere gc</em> is run. You can also use more human-readable &quot;1.month.ago&quot;, etc. The default is 15 days. See <strong>git-rerere</strong>(1).</p></blockquote><h2 id="notes" tabindex="-1">NOTES <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;NOTES&quot;">​</a></h2><p><em>git gc</em> tries very hard not to delete objects that are referenced anywhere in your repository. In particular, it will keep not only objects referenced by your current set of branches and tags, but also objects referenced by the index, remote-tracking branches, reflogs (which may reference commits in branches that were later amended or rewound), and anything else in the refs/* namespace. Note that a note (of the kind created by <em>git notes</em>) attached to an object does not contribute in keeping the object alive. If you are expecting some objects to be deleted and they aren&#39;t, check all of those locations and decide whether it makes sense in your case to remove those references.</p><p>On the other hand, when <em>git gc</em> runs concurrently with another process, there is a risk of it deleting an object that the other process is using but hasn&#39;t created a reference to. This may just cause the other process to fail or may corrupt the repository if the other process later adds a reference to the deleted object. Git has two features that significantly mitigate this problem:</p><blockquote><p>1.</p><p>Any object with modification time newer than the <strong>--prune</strong> date is kept, along with everything reachable from it.</p></blockquote><blockquote><p>2.</p><p>Most operations that add an object to the database update the modification time of the object if it is already present so that #1 applies.</p></blockquote><p>However, these features fall short of a complete solution, so users who run commands concurrently have to live with some risk of corruption (which seems to be low in practice).</p><h2 id="hooks" tabindex="-1">HOOKS <a class="header-anchor" href="#hooks" aria-label="Permalink to &quot;HOOKS&quot;">​</a></h2><p>The <em>git gc --auto</em> command will run the <em>pre-auto-gc</em> hook. See <strong>githooks</strong>(5) for more information.</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>git-prune</strong>(1) <strong>git-reflog</strong>(1) <strong>git-repack</strong>(1) <strong>git-rerere</strong>(1)</p><h2 id="git" tabindex="-1">GIT <a class="header-anchor" href="#git" aria-label="Permalink to &quot;GIT&quot;">​</a></h2><p>Part of the <strong>git</strong>(1) suite</p>',76);function c(e,p,h,u,d,m){return o(),r("div",null,[s("h1",g,a(e.$params.man),1),l])}const b=t(n,[["render",c]]);export{k as __pageData,b as default};
